/** Systems that actually have at least one question (drives the filter list). */
export const NEURO_MCQ_SYSTEMS: string[] = NEURO_MCQ_SYSTEM_ORDER.filter((s) =>
  NEURO_MCQS.some((q) => q.system === s),
);
